function getPortugalMicroDetails(code: string, cat: string, name: string) {
  let fundsMin = "Portugal C Short Stay Visa requires proof of min EUR 40/day + EUR 75 entry allowance + hotel booking + round-trip ticket + travel medical insurance (min EUR 30,000).";
  let fundsBankMonths = "Last 3 months personal bank statements stamped by bank branch.";
  let fundsSudden = "❌ Sudden cash deposits right before visa submission at VFS Global / AIMA are strictly audited. Maintain steady balance over 3 months.";
  let fundsEx = "✅ Sahi: Seasoned 3-month bank statement with EUR 40/day liquid funds. ❌ Galat: Sudden deposit 24 hours prior to appointment.";

  let itrYears = "Income Tax Returns (ITR) or tax notices for past 2 years.";
  let itrMatch = "Declared income must align with bank account credits and employment contract.";
  let itrNoItr = "Not required for short-term visitors fully sponsored by host via Termo de Responsabilidade.";

  let bankMonths = "Last 3 months bank statements.";
  let bankReg = "Regular salary credits or business revenue.";
  let bankFd = "Fixed deposits accepted as secondary financial proof.";
  let bankSource = "Salary, business income, or verified sponsor funds.";

  const lowerCode = code.toLowerCase();
  if (cat === 'work' || lowerCode.includes('wrk') || lowerCode.includes('d1') || lowerCode.includes('blue-card')) {
    fundsMin = "Portugal Work Visa (D1 Work Permit / Highly Qualified D3) requires an employment contract or binding job offer registered with AIMA/IEFP + minimum salary meeting Portuguese National Minimum Wage (SMN EUR 820/month, or EUR 35,000/year for EU Blue Card).";
    fundsBankMonths = "Employer employment contract, IEFP declaration, and 3 months personal bank statements.";
    fundsSudden = "Contract must state gross monthly salary, duration, and position.";
    fundsEx = "✅ Sahi: Signed employment contract + IEFP declaration + 3M bank statements. ❌ Galat: Salary below SMN EUR 820/month.";
  } else if (cat === 'student' || lowerCode.includes('stu') || lowerCode.includes('d4')) {
    fundsMin = "Portugal Student Residence Permit (D4) requires official admission letter from an accredited Portuguese university + tuition fee receipt + proof of living funds of at least EUR 820/month (SMN) or EUR 9,840/year in a bank account.";
    fundsBankMonths = "3 months bank statements showing min EUR 820/month liquid funds.";
    fundsSudden = "Sponsor or personal bank statement must prove regular financial availability.";
    fundsEx = "✅ Sahi: University acceptance letter + tuition fee receipt + EUR 9,840 bank proof. ❌ Galat: Unverified sponsor funds.";
  } else if (cat === 'family' || lowerCode.includes('fam') || lowerCode.includes('d6') || lowerCode.includes('reagrupamento')) {
    fundsMin = "Portugal Family Reunification Permit (D6 Reagrupamento Familiar) requires sponsor residing in Portugal to demonstrate financial capability (min 100% SMN EUR 820/month for sponsor + 50% for spouse + 30% per child) + accommodation proof + Termo de Responsabilidade.";
    fundsBankMonths = "3-6 months sponsor bank statements, tax returns (IRS), and NIF proof in Portugal.";
    fundsSudden = "Termo de Responsabilidade signed and notarized in Portugal.";
    fundsEx = "✅ Sahi: Notarized Termo de Responsabilidade + sponsor income (EUR 820+/month) + apostilled marriage/birth certificate. ❌ Galat: Sponsor income below minimum threshold.";
  } else if (cat === 'business' || lowerCode.includes('biz') || lowerCode.includes('d2') || lowerCode.includes('golden') || lowerCode.includes('ari')) {
    fundsMin = "Portugal C Business / D2 Entrepreneur / Golden Visa ARI requires company registration with Conservatória do Registo Comercial + for Golden Visa, investment of EUR 500,000 in qualifying funds + NIF tax number and Portuguese bank account.";
    fundsBankMonths = "3-6 months corporate and personal bank statements.";
    fundsSudden = "Company registration with Conservatória do Registo Comercial is mandatory.";
    fundsEx = "✅ Sahi: Conservatória company registration + EUR 500k fund proof / D2 business plan + NIF. ❌ Galat: Unregistered firm or real estate investment (closed 2023).";
  } else if (cat === 'pr' || lowerCode.includes('pr') || lowerCode.includes('residência-permanente') || lowerCode.includes('spe')) {
    fundsMin = "Portugal Permanent Residence (Autorização de Residência Permanente) / Naturalization requires 5 years continuous legal residence in Portugal + CIPLE Portuguese language test (Level A2) + clean criminal record + tax clearance with Finanças.";
    fundsBankMonths = "5 years residence history, IRS tax returns, and bank statements.";
    fundsSudden = "Continuous legal residence evaluated by AIMA.";
    fundsEx = "✅ Sahi: 5 years legal residence + CIPLE A2 certificate + Finanças tax clearance. ❌ Galat: Unexcused gap in legal stay or tax arrears.";
  }

  return {
    fundsBox: { minimum: fundsMin, bankMonths: fundsBankMonths, suddenDeposit: fundsSudden, example: fundsEx },
    itrBox: { years: itrYears, match: itrMatch, noItr: itrNoItr },
    bankBox: { months: bankMonths, regularCredit: bankReg, fd: bankFd, source: bankSource }
  };
}

