function convertRawToVisaItem(item: RawPortugalItem): VisaItem {
  const docList = item.docs ? item.docs.split(' + ') : [];
  const details = getPortugalMicroDetails(item.id, item.category, item.name);

  return {
    id: item.id,
    name: item.name,
    officialCode: item.officialCode,
    categoryCode: item.category,
    fee: item.fee,
    validity: item.validity,
    stay: item.validity,
    purpose: `Official ${item.category} visa and residence permit entry for Portugal (AIMA / VFS Global).`,
    eligibility: "Valid passport with min 3 months validity, 2 blank pages, travel medical insurance EUR 30,000, confirmed travel itinerary / employment contract / university admission / Termo de Responsabilidade, and financial proof.",
    popular: item.id === 'pt-TOU-001' || item.id === 'pt-BIZ-001' || item.id === 'pt-WRK-001' || item.id === 'pt-STU-001' || item.id === 'pt-FAM-001' || item.id === 'pt-PR-001' || item.id === 'pt-TOU-010' || item.id === 'pt-TOU-011',
    highlight: item.id === 'pt-TOU-001' || item.id === 'pt-WRK-001' || item.id === 'pt-TOU-010' || item.id === 'pt-TOU-011',
    record_type: item.record_type,
    toCountry: item.toCountry,
    fromCountry: item.fromCountry,
    warningBox: item.warningBox,
    rawFundsBox: item.fundsBox,
    rawBankBox: item.bankBox,
    docs: docList,
    fundsBox: details.fundsBox,
    itrBox: details.itrBox,
    bankBox: details.bankBox
  };
}

export const PORTUGAL_94_VISAS: CountryVisas = {
  tourist: RAW_PT_ITEMS.filter(i => i.category === 'tourist').map(convertRawToVisaItem),
  business: RAW_PT_ITEMS.filter(i => i.category === 'business').map(convertRawToVisaItem),
  work: RAW_PT_ITEMS.filter(i => i.category === 'work').map(convertRawToVisaItem),
  student: RAW_PT_ITEMS.filter(i => i.category === 'student').map(convertRawToVisaItem),
  family: RAW_PT_ITEMS.filter(i => i.category === 'family').map(convertRawToVisaItem),
  pr: RAW_PT_ITEMS.filter(i => i.category === 'pr').map(convertRawToVisaItem)
};
